starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_kms_key" "this" {
  # TODO - Complete the aws_kms_key resource.
  # Add the arguments and nested blocks required for aws_kms_key.
}

starter.outputs.tf:
output "key_arn" {
  value = aws_kms_key.this.arn
}

output "key_id" {
  value = aws_kms_key.this.arn
}
